({
  _ensureInitialized() {
    if (!this.data || typeof this.data !== 'object') {
      this.data = {};
    }
    if (!this.data.rates || typeof this.data.rates !== 'object') {
      this.data.rates = {};
    }
  },

  _checkInvariants() {
    this.invariant(this.data && typeof this.data === 'object', 'Model data must be an object');
    this.invariant(this.data.rates && typeof this.data.rates === 'object', 'Rates table must be an object');
    for (const [pair, rate] of Object.entries(this.data.rates)) {
      this.invariant(
        typeof rate === 'number' && Number.isFinite(rate) && rate > 0,
        `Exchange rate for ${pair} must be a positive finite number`
      );
    }
  },

  _getRate(from, to) {
    if (from === to) return 1.0;
    const directKey = `${from}_${to}`;
    if (typeof this.data.rates[directKey] === 'number') {
      return this.data.rates[directKey];
    }
    const inverseKey = `${to}_${from}`;
    if (typeof this.data.rates[inverseKey] === 'number' && this.data.rates[inverseKey] > 0) {
      return 1.0 / this.data.rates[inverseKey];
    }
    return null;
  },

  setRate(msg) {
    this._ensureInitialized();
    const payload = msg?.payload || {};
    const { from, to, rate } = payload;

    // Preconditions
    this.ensure(typeof from === 'string' && from.trim().length > 0, 'Source currency "from" must be a non-empty string');
    this.ensure(typeof to === 'string' && to.trim().length > 0, 'Target currency "to" must be a non-empty string');
    this.ensure(typeof rate === 'number' && Number.isFinite(rate) && rate > 0, 'Exchange rate "rate" must be a positive finite number');

    const source = from.trim().toUpperCase();
    const target = to.trim().toUpperCase();
    const pairKey = `${source}_${target}`;

    // Mutation
    this.data.rates[pairKey] = rate;
    this._checkInvariants();

    const response = { from: source, to: target, rate };

    // Postconditions
    this.ensure(this.data.rates[pairKey] === rate, 'Exchange rate must be persisted in rates store');
    this.changed('rates', response);

    return response;
  },

  convert(msg) {
    this._ensureInitialized();
    const payload = msg?.payload || {};
    const { amount, from, to } = payload;

    // Preconditions
    this.ensure(typeof amount === 'number' && Number.isFinite(amount), 'Amount must be a finite number');
    this.ensure(typeof from === 'string' && from.trim().length > 0, 'Source currency "from" must be a non-empty string');
    this.ensure(typeof to === 'string' && to.trim().length > 0, 'Target currency "to" must be a non-empty string');

    const source = from.trim().toUpperCase();
    const target = to.trim().toUpperCase();
    const rate = this._getRate(source, target);

    this.ensure(rate !== null, `Exchange rate from ${source} to ${target} is not available`);

    const result = amount * rate;

    // Postcondition
    this.ensure(typeof result === 'number' && Number.isFinite(result), 'Conversion result must be a valid finite number');

    return {
      amount,
      from: source,
      to: target,
      rate,
      result
    };
  },

  convertMultiple(msg) {
    this._ensureInitialized();
    const payload = msg?.payload || {};
    const { amount, from, targets } = payload;

    // Preconditions
    this.ensure(typeof amount === 'number' && Number.isFinite(amount), 'Amount must be a finite number');
    this.ensure(typeof from === 'string' && from.trim().length > 0, 'Source currency "from" must be a non-empty string');
    this.ensure(Array.isArray(targets) && targets.length > 0, 'Targets must be a non-empty array of currency codes');

    const source = from.trim().toUpperCase();
    const conversions = {};

    for (const targetItem of targets) {
      this.ensure(typeof targetItem === 'string' && targetItem.trim().length > 0, 'Target currency must be a non-empty string');
      const target = targetItem.trim().toUpperCase();
      const rate = this._getRate(source, target);
      this.ensure(rate !== null, `Exchange rate from ${source} to ${target} is not available`);
      conversions[target] = {
        rate,
        result: amount * rate
      };
    }

    const response = {
      amount,
      from: source,
      conversions
    };

    // Postcondition
    this.ensure(
      response && typeof response === 'object' && Object.keys(response.conversions).length === targets.length,
      'All requested currency conversions must be computed successfully'
    );

    return response;
  }
})
